/**
 * 🌐 Idiomas del sitio web público (español, inglés, francés y portugués).
 * Los textos fijos del sitio se traducen con este diccionario; el contenido que escribe la institución
 * (nombres y descripciones de cursos) lo puede traducir además el navegador del visitante.
 */
export const SITE_LANGS = [['es', 'Español', 'ES'], ['en', 'English', 'EN'], ['fr', 'Français', 'FR'], ['pt', 'Português', 'PT']] as const;
export type SiteLang = (typeof SITE_LANGS)[number][0];
export const LANG_COOKIE = 'sitio-lang';
export const isSiteLang = (l: unknown): l is SiteLang => typeof l === 'string' && SITE_LANGS.some(([c]) => c === l);

